 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    row_bars = [r for r in range(h) if all(v == 8 for v in grid[r])]
    col_bars = [c for c in range(w) if all(grid[r][c] == 8 for r in range(h))]

    def blocks(size, bars):
        result = []
        start = 0
        for bar in bars:
            if start < bar:
                result.append((start, bar))
            start = bar + 1
        if start < size:
            result.append((start, size))
        return result

    rows, cols = blocks(h, row_bars), blocks(w, col_bars)
    seeds = {2: set(), 3: set()}
    for i, (r0, r1) in enumerate(rows):
        for j, (c0, c1) in enumerate(cols):
            for r in range(r0, r1):
                for c in range(c0, c1):
                    if grid[r][c] in seeds:
                        seeds[grid[r][c]].add((i, j))

    paths = {2: set(), 3: set()}
    for color, points in seeds.items():
        points = list(points)
        for a in range(len(points)):
            r1, c1 = points[a]
            for b in range(a + 1, len(points)):
                r2, c2 = points[b]
                if r1 == r2:
                    for c in range(min(c1, c2), max(c1, c2) + 1):
                        paths[color].add((r1, c))
                if c1 == c2:
                    for r in range(min(r1, r2), max(r1, r2) + 1):
                        paths[color].add((r, c1))

    out = [row[:] for row in grid]
    for i, (r0, r1) in enumerate(rows):
        for j, (c0, c1) in enumerate(cols):
            color = 6 if (i, j) in paths[2] and (i, j) in paths[3] else (2 if (i, j) in paths[2] else (3 if (i, j) in paths[3] else 0))
            if color:
                for r in range(r0, r1):
                    for c in range(c0, c1):
                        out[r][c] = color
    return out
"
